@SpringBootTest
@Testcontainers
@ActiveProfiles("test")
public class OrderServiceIntegrationTest {

    @Container
    @ServiceConnection
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:15-alpine");

    @Autowired
    private OrderRepository orderRepository;

    @Test
    void shouldPersistAndRetrieveOrderWithNativeTypes() {
        Order order = new Order("TXN-998877", BigDecimal.valueOf(150.00));
        orderRepository.save(order);

        Optional<Order> fetched = orderRepository.findByTransactionId("TXN-998877");
        assertThat(fetched).isPresent();
        assertThat(fetched.get().getAmount()).isEqualByComparingTo("150.00");
    }
}
